package org.example.backend.controller;
import org.example.backend.entity.ReservationStatus;
import org.example.backend.service.*;
import org.example.backend.security.AuthenticationAttributes;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

class ReservationEndpointBehaviorTest {
    final ReservationCatalogQuery catalog=mock(ReservationCatalogQuery.class);
    final ReservationCommandHandler commands=mock(ReservationCommandHandler.class);
    MockMvc mvc;
    ReservationView view(ReservationStatus status){return new ReservationView(9L,7L,"教师甲","学院","123",1L,LocalDate.of(2027,1,4),"08:30-10:00","教学",20,"上机",status,status==ReservationStatus.CONFLICT,"审批人","通过",LocalDateTime.of(2026,10,18,10,0),LocalDateTime.of(2026,10,18,11,0),"机房","A101");}
    @BeforeEach void setup(){mvc=MockMvcBuilders.standaloneSetup(new ReservationController(catalog,commands)).build();}
    @Test void authenticatedListAndDetailReturnLegacyAliasesAndCanonicalFields() throws Exception{when(catalog.list(any())).thenReturn(List.of(view(ReservationStatus.APPROVED)));when(catalog.findById(eq(9L),any())).thenReturn(view(ReservationStatus.PENDING));mvc.perform(get("/reservations").requestAttr(AuthenticationAttributes.USER_ID,7).requestAttr(AuthenticationAttributes.ROLE,"teacher")).andExpect(jsonPath("$.data[0].applicant").value("教师甲")).andExpect(jsonPath("$.data[0].applicantName").value("教师甲")).andExpect(jsonPath("$.data[0].lab").value("A101 机房")).andExpect(jsonPath("$.data[0].date").value("2027-01-04")).andExpect(jsonPath("$.data[0].tagType").value("success"));verify(catalog).list(ReservationAccessScope.forActor(ReservationActor.teacher(7)));mvc.perform(get("/reservations/9").requestAttr(AuthenticationAttributes.USER_ID,"7").requestAttr(AuthenticationAttributes.ROLE,"labAdmin")).andExpect(jsonPath("$.data.id").value(9));mvc.perform(get("/reservations/10").requestAttr(AuthenticationAttributes.USER_ID,7).requestAttr(AuthenticationAttributes.ROLE,"systemAdmin")).andExpect(jsonPath("$.data").doesNotExist());}
    @Test void unauthenticatedMalformedAndUnknownActorsCannotReadReservations() throws Exception{mvc.perform(get("/reservations")).andExpect(status().isForbidden());for(Object userId:List.of(0,-1,"bad"))mvc.perform(get("/reservations").requestAttr(AuthenticationAttributes.USER_ID,userId).requestAttr(AuthenticationAttributes.ROLE,"labAdmin")).andExpect(status().isForbidden());mvc.perform(get("/reservations").requestAttr(AuthenticationAttributes.USER_ID,7).requestAttr(AuthenticationAttributes.ROLE,"unknown")).andExpect(status().isForbidden());verifyNoInteractions(catalog,commands);}
    @Test void createBindsAliasesButActorIdentityComesOnlyFromAuthenticatedRequest() throws Exception{when(commands.create(any(),any())).thenReturn(view(ReservationStatus.PENDING));mvc.perform(post("/reservations").requestAttr(AuthenticationAttributes.USER_ID,7).requestAttr(AuthenticationAttributes.ROLE,"teacher").contentType(MediaType.APPLICATION_JSON).content("{\"applicant\":\"教师甲\",\"applicantUserId\":999,\"department\":\"学院\",\"contact\":\"123\",\"labId\":1,\"date\":\"2027-01-04\",\"timeRange\":\"08:30-10:00\",\"scene\":\"教学\",\"attendees\":20,\"reason\":\"上机\"}" )).andExpect(jsonPath("$.data.id").value(9));verify(commands).create(eq(new CreateReservationCommand("教师甲","学院","123",1L,LocalDate.of(2027,1,4),"08:30-10:00","教学",20,"上机")),eq(ReservationActor.teacher(7)));}
    @Test void reviewRequiresAuthenticatedNameAndMapsOptionalReviewBody() throws Exception{when(commands.approve(any(),any())).thenReturn(view(ReservationStatus.APPROVED));when(commands.reject(any(),any())).thenReturn(view(ReservationStatus.REJECTED));mvc.perform(post("/reservations/9/approve").requestAttr(AuthenticationAttributes.USER_ID,7).requestAttr(AuthenticationAttributes.ROLE,"labAdmin")).andExpect(status().isForbidden());mvc.perform(post("/reservations/9/approve").requestAttr(AuthenticationAttributes.USER_ID,7).requestAttr(AuthenticationAttributes.ROLE,"labAdmin").requestAttr(AuthenticationAttributes.USERNAME,"审批人")).andExpect(jsonPath("$.data.status").value("已通过"));verify(commands).approve(new ReviewReservationCommand(9L,null),ReservationActor.laboratoryAdministrator(7,"审批人"));mvc.perform(post("/reservations/9/reject").requestAttr(AuthenticationAttributes.USER_ID,7).requestAttr(AuthenticationAttributes.ROLE,"systemAdmin").requestAttr(AuthenticationAttributes.USERNAME,"审批人").contentType(MediaType.APPLICATION_JSON).content("{\"reviewRemark\":\"不符合要求\"}" )).andExpect(jsonPath("$.data.status").value("已驳回"));verify(commands).reject(new ReviewReservationCommand(9L,"不符合要求"),ReservationActor.systemAdministrator(7,"审批人"));}
    @Test void responseTagsReflectEveryLifecycleStateAndNullDatesRemainDisplaySafe(){for(ReservationStatus status:ReservationStatus.values()){ReservationResponse result=ReservationResponse.from(view(status));assertEquals(status.storageValue(),result.status());assertEquals(result.applicantName(),result.applicant());assertEquals(result.attendeeCount(),result.attendees());assertEquals(status==ReservationStatus.CONFLICT,result.conflict());assertNotNull(result.tagType());}ReservationView sparse=new ReservationView(1L,null,null,null,null,null,null,null,null,null,null,null,false,null,null,null,null,null,null);ReservationResponse result=ReservationResponse.from(sparse);assertEquals("",result.lab());assertEquals("",result.date());assertEquals("",result.submittedAt());assertEquals("-",result.reviewedAt());assertEquals("待审核",result.reviewer());assertNull(ReservationResponse.from(null));}
}
